def count_levels(lines):
    counts = {}
    for line in lines:
        for level in ('ERROR', 'WARN', 'INFO'):
            if f' {level} ' in line or f' {level}  ' in line:
                counts[level] = counts.get(level, 0) + 1
                break
    return counts

stats = count_levels(log)
print(stats)
