def desired_replicas(current, load, low, high, min_r, max_r):
    target = current
    if load > high:
        target = current + 1
    elif load < low:
        target = current - 1
    return max(min_r, min(max_r, target))

replicas = 2
for minute, load in enumerate([20, 45, 80, 95, 90, 60, 25, 10], start=1):
    new = desired_replicas(replicas, load, 30, 70, 2, 6)
    mark = "=" if new == replicas else ("+" if new > replicas else "-")
    print(f"минута {minute}: нагрузка {load:>3}%  реплик {replicas} -> {new}  {mark}")
    replicas = new

